"use client"


function WordCounter() {

  const [wordCounter, setwordCounter] = useState("")
  return (
    <>
      <div>
        <h2>Word Counter Component</h2>
        <p>This is a placeholder for the Word Counter functionality.</p>
        <input type="text" value={wordCounter} onChange={e => setwordCounter(e.target.value)} />
        <p>Words number is : {wordCounter}</p>
      </div>
    </>
  )


}


export default WordCounter